-- ============================================================
-- V21: Append full visual_spec examples to the Video Script Generator skill
-- so the LLM imitates rich, varied scenes (hero, grid/cards, timeline, flow)
-- instead of sparse single-box scenes.
-- ============================================================

UPDATE public.skills
SET content = content || E'\n\n## Worked examples (imitate these)\n\n### Example 1 - Hero intro (layout "hero")\n{\n  "title": "INTRODUCTION",\n  "subtitle": "Why this topic matters",\n  "theme": "corporate",\n  "layout": "hero",\n  "components": [\n    { "id": "h1", "type": "title-card", "label": "JAVA MEMORY MANAGEMENT", "fill": "#eff6ff", "line": "#2563eb" },\n    { "id": "h2", "type": "bullet-card", "label": "What you will learn", "items": ["Stack vs Heap", "Garbage Collection", "OutOfMemoryError causes"], "fill": "#f0fdf4", "line": "#16a34a" }\n  ],\n  "instructions": [ "Stay with us - each concept builds on the last" ]\n}\n\n### Example 2 - Cards grid (layout "cards")\n{\n  "title": "THREE MEMORY REGIONS",\n  "subtitle": "Each region has a clear responsibility",\n  "theme": "corporate",\n  "layout": "cards",\n  "components": [\n    { "id": "c1", "type": "info-card", "label": "STACK", "sublabel": "Method frames & local variables", "fill": "#eff6ff", "line": "#2563eb" },\n    { "id": "c2", "type": "info-card", "label": "HEAP", "sublabel": "Objects live here", "fill": "#fef3c7", "line": "#d97706" },\n    { "id": "c3", "type": "info-card", "label": "METASPACE", "sublabel": "Class metadata", "fill": "#fce7f3", "line": "#db2777" },\n    { "id": "c4", "type": "summary-card", "label": "KEY IDEA", "items": ["Stack is fast and per-thread", "Heap is shared and GC-managed"], "fill": "#f0fdf4", "line": "#16a34a" }\n  ],\n  "instructions": [ "Memorize one region per card" ]\n}\n\n### Example 3 - Timeline (layout "timeline")\n{\n  "title": "OBJECT LIFECYCLE",\n  "subtitle": "Birth to collection",\n  "theme": "technical",\n  "layout": "timeline",\n  "components": [\n    { "id": "t1", "type": "pill-card", "label": "NEW", "sublabel": "allocated on heap", "fill": "#eff6ff", "line": "#2563eb" },\n    { "id": "t2", "type": "pill-card", "label": "REACHABLE", "sublabel": "referenced by GC roots", "fill": "#f0fdf4", "line": "#16a34a" },\n    { "id": "t3", "type": "pill-card", "label": "UNREACHABLE", "sublabel": "no live references", "fill": "#fef3c7", "line": "#d97706" },\n    { "id": "t4", "type": "pill-card", "label": "COLLECTED", "sublabel": "finalized & swept", "fill": "#fee2e2", "line": "#dc2626" }\n  ],\n  "connections": [ { "from": "t1", "to": "t2", "label": "assignment", "kind": "default" }, { "from": "t2", "to": "t3", "label": "lose ref", "kind": "default" }, { "from": "t3", "to": "t4", "label": "GC runs", "kind": "default" } ],\n  "instructions": [ "Trace each phase with the narration" ]\n}\n\n### Example 4 - Flow diagram (layout "flow")\n{\n  "title": "HOW A NEW OBJECT IS CREATED",\n  "subtitle": "new keyword end to end",\n  "theme": "whiteboard",\n  "layout": "flow",\n  "components": [\n    { "id": "a", "type": "oval", "label": "START", "fill": "#eff6ff", "line": "#2563eb" },\n    { "id": "b", "type": "box", "label": "LOAD CLASS", "fill": "#fef3c7", "line": "#d97706" },\n    { "id": "c", "type": "box", "label": "ALLOCATE HEAP", "fill": "#f0fdf4", "line": "#16a34a" },\n    { "id": "d", "type": "box", "label": "RUN CONSTRUCTOR", "fill": "#fce7f3", "line": "#db2777" },\n    { "id": "e", "type": "oval", "label": "END", "fill": "#eff6ff", "line": "#2563eb" }\n  ],\n  "connections": [ { "from": "a", "to": "b", "kind": "default" }, { "from": "b", "to": "c", "kind": "default" }, { "from": "c", "to": "d", "kind": "default" }, { "from": "d", "to": "e", "kind": "default" } ],\n  "instructions": [ "Every step adds overhead - design objects thoughtfully" ]\n}\n'
WHERE id = 'a0000000-0000-0000-0000-000000000001'
  AND content NOT LIKE '%Worked examples (imitate these)%';
